function measure(){if(garmentMode())return garmentMeasure();const step=draft.step,max=draft.method==='ready'?2:3,review=step===max;let title,content,draw=fields.find(f=>f.group===step)?.id||'chest';if(step===0){title='How would you like to find your fit?';content=`<p>Choose the starting point that works for you.</p><label class="field">Who are these measurements for?<select aria-label="Who are these measurements for" onchange="draft.wearer=this.value;saveDraft();render(false)"><option value=""${draft.wearer?'':' selected'}>Choose who you are measuring</option>${WEARERS.map(w=>`<option value="${w}"${draft.wearer===w?' selected':''}>${w}</option>`).join('')}</select></label><div class="method-cards"><button class="method ${draft.method==='body'?'active':''}" onclick="setMethod('body')"><span><strong>Measure my body</strong><small>Guided body measurements with clear illustrations.</small></span><span>↗</span></button><button class="method ${draft.method==='ready'?'active':''}" onclick="setMethod('ready')"><span><strong>Use a standard size</strong><small>Select a familiar jacket and trouser size.</small></span><span>↗</span></button></div><div class="note">For body measurements, you’ll need a flexible tape measure, light clothing, and ideally a helper. Measure naturally without adding extra room.</div>`}else if(review){title='A final look at your fit.';content=`<p>Review your details before saving your profile.</p><label class="field">Profile name<input id="profileName" maxlength="60" value="${esc(draft.name)}" oninput="draft.name=this.value;saveDraft()" placeholder="e.g. My wedding suit"></label><div class="review-list">${draft.method==='ready'?Object.entries(draft.ready).map(([k,v])=>`<div><span>${{jacket:'Jacket size (US)',length:'Jacket length',trouser:'Trouser size (US)'}[k]}</span><strong>${esc(v)}</strong></div>`).join(''):fields.map(f=>`<div><span>${f.label}</span><strong>${displayValue(f.id)} ${draft.unit}</strong></div>`).join('')}</div><label class="field">Preferred fit<select onchange="draft.fit=this.value;saveDraft()">${['Slim','Tailored','Relaxed'].map(v=>`<option ${draft.fit===v?'selected':''}>${v}</option>`).join('')}</select></label><label style="font-size:16px;display:flex;gap:10px;align-items:start"><input id="confirmMeasures" type="checkbox" style="width:16px;margin-top:3px">I’ve double-checked my ${draft.method==='ready'?'size selections':'body measurements'}.</label>`}else if(draft.method==='ready'){title='Your familiar sizes.';content=`<p>Choose US sizes. These are standard size selections, not a custom body measurement profile.</p><label class="field">Jacket size (US)<select aria-label="Jacket size" onchange="draft.ready.jacket=this.value;saveDraft()"><option value="" ${draft.ready.jacket?'':'selected'}>Choose a jacket size</option>${READY_SIZE_SETS.jacket.map(n=>`<option ${draft.ready.jacket==n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Jacket length<select aria-label="Jacket length" onchange="draft.ready.length=this.value;saveDraft()"><option value="" ${draft.ready.length?'':'selected'}>Choose a jacket length</option>${READY_SIZE_SETS.lengths.map(v=>`<option ${draft.ready.length===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Trouser size (US)<select aria-label="Trouser size" onchange="draft.ready.trouser=this.value;saveDraft()"><option value="" ${draft.ready.trouser?'':'selected'}>Choose a trouser size</option>${READY_SIZE_SETS.trouser.map(n=>`<option ${draft.ready.trouser==n?'selected':''}>${n}</option>`).join('')}</select></label><button type="button" class="textlink" aria-expanded="${sizeGuideOpen}" aria-controls="sizeGuide" onclick="toggleSizeGuide()">Size guide</button>${sizeGuideOpen?sizeGuideHtml():''}<div class="note">Between sizes or unsure? Go back and choose guided body measurements, or visit a showroom for a fitting.</div>`}else{title=step===1?'Let’s start with your jacket.':'Now, your trousers.';content=`<p>Enter your body measurements. Keep the tape close, without pulling it tight.</p><div class="units" aria-label="Measurement units"><button class="${draft.unit==='in'?'active':''}" onclick="changeUnit('in')">inches</button><button class="${draft.unit==='cm'?'active':''}" onclick="changeUnit('cm')">cm</button></div><div class="input-grid">${fields.filter(f=>f.group===step).map(measureBounds).map(fieldHtml).join('')}</div><p class="subtle">Select any field to see where and how to measure.</p>`}return `<section class="measurement-shell"><div class="measurement-heading"><div class="eyebrow">THE MEASUREMENT STUDIO</div><h1>Your fit. Without the guesswork.</h1><p>A little guidance. A more personal fit.</p></div><div class="progress-nav">${(draft.method==='ready'?['Your method','Your sizes','Review & save']:['Your method','Your jacket','Your trousers','Review & save']).map((s,i)=>`<span class="${i===step?'active':''}">${i<step?'✓':String(i+1).padStart(2,'0')} &nbsp; ${s}</span>`).join('')}</div><div class="measure-card"><div class="illustration"><div id="bodyDrawing">${figure(draw)}</div><p id="drawingTip">${step>0&&!review&&draft.method==='body'?fields.find(f=>f.id===draw).tip:'Stand naturally. Wear light clothing. Let the tape follow your body.'}</p></div><div class="measure-content"><div class="eyebrow">STEP ${step+1} OF ${max+1}</div><div class="bar"><span style="width:${(step+1)/(max+1)*100}%"></span></div><h2>${title}</h2>${content}<div class="error" id="measureError" role="alert"></div><div class="measure-bottom">${step?'<button class="textlink icon" onclick="measureBack()">← Back</button>':'<span class="subtle">A profile you can use again.</span>'}<button class="btn orange" onclick="measureNext()">${review?'Save my profile':'Continue'} <span>→</span></button></div></div></div><p class="saved-note">Progress saved on this browser · You can come back whenever you’re ready.</p></section>`}
function measureBack(){draft.step--;saveDraft();render(false)}
function bodyProblemMessage(f){return `Please check ${f.label.toLowerCase()}. Enter a measurement between ${Math.round(f.min*(draft.unit==='cm'?2.54:1))} and ${Math.round(f.max*(draft.unit==='cm'?2.54:1))} ${draft.unit}, or contact a fitter for guidance.`}
function bodyStepProblems(step){return fields.filter(f=>f.group===step).map(measureBounds).filter(f=>!Number.isFinite(draft.values[f.id])||draft.values[f.id]<f.min||draft.values[f.id]>f.max)}
function measureNext(){if(garmentMode()){garmentMeasureNext();return}if(draft.step===0&&!WEARERS.includes(draft.wearer)){$('#measureError').textContent='Choose who these measurements are for to continue.';return}const max=draft.method==='ready'?2:3;if(draft.step>0&&draft.step<max&&draft.method==='body'){const problems=bodyStepProblems(draft.step);fields.filter(f=>f.group===draft.step).forEach(f=>{const input=document.getElementById('measureInput-'+f.id);if(input){if(problems.some(p=>p.id===f.id))input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid')}});if(problems.length){const box=$('#measureError');if(problems.length===1)box.textContent=bodyProblemMessage(problems[0]);else box.innerHTML=`Please check these ${problems.length} measurements before you continue:<ul>${problems.map(f=>`<li>${esc(bodyProblemMessage(f))}</li>`).join('')}</ul>`;return}}
if(draft.step>0&&draft.step<max&&draft.method==='ready'){const miss=missingReady();if(miss.length){$('#measureError').textContent='Choose your '+miss.join(', ')+' to continue. No standard size is preselected.';return}}
if(draft.step===max){if(draft.method==='ready'){const miss=missingReady();if(miss.length){$('#measureError').textContent='Choose your '+miss.join(', ')+' before saving your profile.';return}}if(!draft.name.trim()){$('#measureError').textContent='Give your measurement profile a name.';return}if(!$('#confirmMeasures').checked){$('#measureError').textContent='Please confirm you’ve checked your measurements.';return}const p={...JSON.parse(JSON.stringify(draft)),id:uid(),name:draft.name.trim(),created:new Date().toISOString(),version:1};profiles.push(p);write('suits-profiles',profiles);if(typeof syncProfileToAccount==='function')syncProfileToAccount(p);config.profileId=p.id;saveConfig();draft.step=0;saveDraft();if(returnToSuit){stage=2;returnToSuit=false;location.hash='#customize';render();toast('Measurement profile saved. Your suit is ready to review.')}else openModal(`<div class="eyebrow">A MORE PERSONAL FIT</div><h2>Your profile is ready.</h2><p>${esc(p.name)} is saved on this browser. You can reuse it when you customize your next suit.</p><button class="btn orange" onclick="closeModal();location.hash='#customize'">Design my suit →</button><button class="btn light" style="margin-top:12px" onclick="openProfiles()">View my profiles</button>`);return}draft.step++;saveDraft();render(false)}function updateBag(){$('#bagCount').textContent=bag.length}
function openModal(s){$('#modalContent').innerHTML=s;if(!$('#modal').open)$('#modal').showModal()}function closeModal(){$('#modal').close()}
// Wave 5 package 5.4 (ACC-01, SIZ-04): the profiles modal status
// line reads the account state the client boots with (complete.js).
// While accounts are not enabled the line is the one the modal has
// always carried, word for word. Package 5.5 adds the write through
// state behind the signed in line: while a save to the account is
// still outstanding, the modal says so in the design's words
// (section 5.2) instead of claiming the profile is synced.
function profileStatusHtml(){const acct=typeof accountState!=='undefined'?accountState:null;if(!acct||!acct.enabled)return 'Saved on this browser. These profiles are not synced to an account.';if(acct.user){if(typeof profileSyncPending!=='undefined'&&profileSyncPending.size)return 'Not saved to your account yet. Your changes are saved on this browser and will be added to your account when the connection works again.';return 'Profiles save to your account and this browser.'}return `Profiles are saved on this browser. <a href="${realUrl('#sign-in')}" onclick="closeModal()">Sign in</a> to keep them with your account.`}
function openProfiles(){openModal(`<div class="eyebrow">YOUR PERSONAL FIT</div><h2>Measurement profiles.</h2><p class="subtle">${profileStatusHtml()}</p>${profiles.length?profiles.map(p=>`<div class="profile-item"><h3>${esc(p.name)}</h3><p class="subtle">${p.method==='ready'?'Standard sizing':p.method==='garment'?profileMeasureCount(p)+' garment measurements':p.method==='modify'?'Modified standard size':profileMeasureCount(p)+' body measurements'} · ${esc(p.fit)} fit</p><button class="btn light" onclick="useProfile('${p.id}')">Use this profile</button><button class="help" onclick="deleteProfile('${p.id}')">Delete</button></div>`).join(''):'<p class="empty">Your first great fit starts here.</p>'}<button class="btn orange" onclick="closeModal();draft.step=0;saveDraft();location.hash='#measure';render()">Create a profile →</button>`)}
function useProfile(id){config.profileId=id;saveConfig();stage=2;closeModal();location.hash='#customize';render()}
function deleteProfile(id){profiles=profiles.filter(p=>p.id!==id);write('suits-profiles',profiles);if(typeof syncProfileDeleteToAccount==='function')syncProfileDeleteToAccount(id);if(config.profileId===id){delete config.profileId;saveConfig()}openProfiles()}
function openBag(){openModal(`<div class="eyebrow">THOUGHTFULLY CHOSEN</div><h2>Your bag. <span class="subtle">(${bag.length})</span></h2>${bag.length?bag.map(x=>{let p=products[x.product];return `<article class="bag-item"><img src="assets/${p.img}" alt="${p.name}"><div><h3>${p.name}</h3><p>${esc(x.fabric)} · ${esc(x.lapel)} lapel · ${esc(x.fit)} fit</p><p>${esc(x.closure)} · ${esc(x.lining)} lining${x.monogram?' · Monogram: '+esc(x.monogram):''}</p><p>Fit profile: ${esc(x.profile.name)}${x.profile.method==='ready'&&x.profile.ready?' · '+readyProfileSummary(x.profile):x.profile.method==='body'?' · Body measurements ('+esc(x.profile.unit==='cm'?'cm':'in')+')':x.profile.method==='garment'?' · Garment measurements ('+esc(x.profile.unit==='cm'?'cm':'in')+')':x.profile.method==='modify'?' · Modified standard size ('+esc(x.profile.unit==='cm'?'cm':'in')+')':''}</p><button onclick="removeBag('${x.id}')">Remove</button></div><span>$${p.price}</span></article>`}).join('')+`<div class="total"><span>Subtotal</span><span>$${bag.reduce((s,x)=>s+products[x.product].price,0)}</span></div><div class="note">This is a private shopping preview. Payment, shipping, taxes, and order submission are not connected.</div><button class="btn orange" style="width:100%;margin-top:20px" onclick="reviewOrder()">Review configuration →</button>`:'<p class="empty">Something made just for you belongs here.</p><button class="btn orange" onclick="closeModal();location.hash=\'#collection\'">Find your suit →</button>'}`)}
function removeBag(id){bag=bag.filter(x=>x.id!==id);write('suits-bag',bag);updateBag();openBag()}
function garmentProfileReviewRows(x){const setId=setForGarment(x.profile.garment,x.profile.wearer||'Men'),defs=setId?garmentMeasureSetFields(setId):[],rows=[['height','Height'],...defs.map(f=>[f.key,f.label])];return rows.filter(([k])=>Number.isFinite(x.profile.values&&x.profile.values[k])).map(([k,label])=>`<div><span>${label}</span><strong>${Math.round(x.profile.values[k]*(x.profile.unit==='cm'?2.54:1)*10)/10} ${x.profile.unit}</strong></div>`).join('')}
function reviewOrder(){openModal(`<div class="eyebrow">CONFIGURATION REVIEW</div><h2>Every detail, considered.</h2><p>Your selected designs and fit profiles are ready for review. No order has been submitted.</p>${bag.map(x=>`<div class="profile-item"><h3>${products[x.product].name}</h3><p class="subtle">${esc(x.fabric)} · ${esc(x.lapel)} lapel · ${esc(x.closure)} · ${esc(x.lining)} lining · ${esc(x.fit)} fit${x.monogram?' · Monogram: '+esc(x.monogram):''}</p><strong>${esc(x.profile.name)}</strong><div class="review-list">${x.profile.method==='ready'?READY_SUMMARY_ORDER.filter(k=>x.profile.ready[k]!==undefined&&x.profile.ready[k]!==null&&x.profile.ready[k]!=='').map(k=>`<div><span>${READY_PART_LABELS[k]||k}</span><strong>${esc(readyPartDisplay(k,x.profile.ready[k]))}</strong></div>`).join(''):x.profile.method==='garment'?garmentProfileReviewRows(x):x.profile.method==='modify'?modifyProfileReviewRows(x):fields.map(f=>`<div><span>${f.label}</span><strong>${Math.round(x.profile.values[f.id]*(x.profile.unit==='cm'?2.54:1)*10)/10} ${x.profile.unit}</strong></div>`).join('')}</div></div>`).join('')}<button class="btn light" onclick="openBag()">← Return to bag</button>`)}

let lastCategoryRoute='';
function categoryCollection(hash){
 const parts=hash.split('/').map(p=>decodeURIComponent(p));const cat=parts[1]||'Suits',item=parts[2]||'Shop all suits';
 if(lastCategoryRoute!==hash){filter=/wedding|groom/i.test(item)||cat==='Weddings'?'Wedding':/linen/i.test(item)?'Linen':/wool/i.test(item)?'Wool':'All suits';lastCategoryRoute=hash;}
 const available=(cat==='Suits'&&!/tweed|cotton|corduroy|tuxedo|double|three|boys|evening/i.test(item))||(cat==='Weddings'&&!/tweed|seersucker/i.test(item));
 if(!available)return `<section class="collection-hero"><div class="copy"><div class="eyebrow">THE SUITS.ME COLLECTION</div><h1>${esc(item.replace(/^Shop all /i,''))}.</h1><p>${esc(cat)} · Personal tailoring</p></div><img src="assets/model-blue.webp" alt="AI-generated tailoring style inspiration"></section><section class="empty-collection"><div class="eyebrow">COLLECTION PREVIEW</div><h2>A place for every part<br>of your wardrobe.</h2><p>This category is part of the new navigation. Its product catalog has not been added to this preview yet.</p><p>Explore the working men's suit collection, or build a measurement profile.</p><a class="btn orange" href="/collections/suits">Explore suits →</a><a class="btn light" href="/measure">Your measurements →</a></section>`;
 return collection().replace('Your next<br>signature piece.',cat==='Weddings'?'For your<br>big moment.':item==='Shop all suits'?'Your next<br>signature piece.':esc(item)+'.');
}

function render(top=true){let hash=location.hash||'#home';if(hash==='#story'){$('#main').innerHTML=home();document.getElementById('craft').scrollIntoView();return}$('#main').innerHTML=hash.startsWith('#collection')?categoryCollection(hash):hash==='#customize'?customize():hash==='#measure'?measure():home();updateBag();if(top)window.scrollTo({top:0,left:0,behavior:'instant'})}
window.addEventListener('hashchange',()=>{closeModal();render()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});render();
